class Solution {
public:
    int numPoints(vector<vector<int>>& darts, int r) {
        const double EPS = 1e-7;
        int n = darts.size(), best = n ? 1 : 0;
        double R = r;
        auto count = [&](double x, double y) {
            int ans = 0;
            for (auto& p : darts) {
                double dx = p[0] - x, dy = p[1] - y;
                if (dx * dx + dy * dy <= R * R + EPS) ++ans;
            }
            return ans;
        };
        for (int i = 0; i < n; ++i) {
            best = max(best, count(darts[i][0], darts[i][1]));
            for (int j = i + 1; j < n; ++j) {
                double dx = darts[j][0] - darts[i][0];
                double dy = darts[j][1] - darts[i][1];
                double d2 = dx * dx + dy * dy;
                if (d2 > 4 * R * R + EPS || d2 < EPS) continue;
                double dist = sqrt(d2);
                double mx = (darts[i][0] + darts[j][0]) / 2.0;
                double my = (darts[i][1] + darts[j][1]) / 2.0;
                double h = sqrt(max(0.0, R * R - d2 / 4.0));
                double ox = -dy * h / dist, oy = dx * h / dist;
                best = max(best, count(mx + ox, my + oy));
                best = max(best, count(mx - ox, my - oy));
            }
        }
        return best;
    }
};
